const dictionaries = { pt: new Map<string, string>(), fr: new Map<string, string>() };
const normalizeCopy = (value: string) => value.trim().replace(/\s+/g, ' ').replace(/[—–]/g, '-');
for (const line of copy.trim().split('\n')) {
  const [en, pt, fr] = line.split('|');
  if (en && pt && fr) { dictionaries.pt.set(normalizeCopy(en), pt); dictionaries.fr.set(normalizeCopy(en), fr); }
}

export function translate(text: string, locale: Locale): string {
  if (locale === 'en' || !text.trim()) return text;
  const normalized = normalizeCopy(text);
  const dictionary = dictionaries[locale];
  let translated = dictionary.get(normalized);
  if (!translated && normalized === normalized.toUpperCase()) {
    for (const [source, target] of dictionary) {
      if (source.toUpperCase() === normalized) { translated = target.toUpperCase(); break; }
    }
  }
  if (!translated) return text;
  return text.slice(0, text.indexOf(text.trim())) + translated + text.slice(text.trimEnd().length);
}

export function normalizeSearch(value: string) { return value.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLocaleLowerCase(); }
